  if (!state.recentKey) return;
  const hex = toHex(colour, { alpha: state.alpha });
  const kept = [hex, ...recentColours(state).map((one) => toHex(one, { alpha: state.alpha }))]
    .filter((value, index, all) => all.indexOf(value) === index)
    .slice(0, RECENT_CAP);
  try {
    localStorage.setItem(state.recentKey, JSON.stringify(kept));
  } catch {
    // A full or refused store is not a reason to lose the colour the reader
    // just chose. Nothing is announced, because nothing they asked for failed.
  }
