/** Draws the recent row, or leaves it hidden when there is nothing in it. */
function paintRecent(state, ui) {
  if (!ui.recent || !ui.recentRow || !ui.templates.swatch) return;
  const colours = recentColours(state);
  ui.recent.hidden = colours.length === 0;
  ui.recentRow.replaceChildren();
  for (const colour of colours) {
    ui.recentRow.append(swatch(state, ui, toHex(colour, { alpha: state.alpha })));
  }
}

/** One swatch, for the recent row or the Noctua grid. */
